INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-027', TRUE, '安徽农业大学官网', NULL, '我校代表团赴印度尼西亚交流访问', '校内通知', NULL, '2026-11-03', NULL, NULL, NULL, 0.5, 'medium', '[{"text": "我校代表团赴印度尼西亚交流访问 【 发布日期：2026-11-03 】 【 来源：国际交流合作处（港", "quote": "我校代表团赴印度尼西亚交流访问 【 发布日期：2026-11-03 】 【 来源：国际交流合作处（港"}]'::jsonb, '校内通知：我校代表团赴印度尼西亚交流访问', '[{"text": "我校代表团赴印度尼西亚交流访问 【 发布日期：2026-11-03 】 【 来源：国际交流合作处（港", "quote": "我校代表团赴印度尼西亚交流访问 【 发布日期：2026-11-03 】 【 来源：国际交流合作处（港"}]'::jsonb, '我校代表团赴印度尼西亚交流访问 【 发布日期：2026-11-03 】 【 来源：国际交流合作处（港澳台事务办公室） 】 【 点击数： 】 本网讯 10月25日至28日，党委常委、副校长李红率团赴印度尼西亚开展访问交流。 代表团先后访问穆拉瓦曼大学、东加里曼丹省农业种植局、畜牧与动物健康局和加查马达大学，围绕科研平台建设、农业科技合作、人才培养和师生互访等议题开展深入交流，持续深化我校与印度尼西亚高校及相关部门的务实合作，着力构建区域农业科教协同创新合作网络。 在穆拉瓦曼大学，双方在去年签署校际合作备忘录的基础上，', 'http://news.ahau.edu.cn/info/1005/143357.htm', '安徽农业大学官网', 'www', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at